import { useEffect, useMemo, useRef, useState } from 'react'
import { ArrowDown, ArrowUp, Bolt, CalendarDays, Check, ChevronDown, ChevronRight, Copy, Eye, EyeOff, ExternalLink, Filter, GripVertical, KanbanSquare, LayoutGrid, Plus, Search, Settings2, Sparkles, Table2, Trash2, X } from 'lucide-react'
import { Link, useParams } from 'react-router-dom'
import { useAppContext } from '../App'
import { createAutomation, createField, createRecord, createView, deleteAutomation, deleteField, deleteRecord, deleteView, ensureDefaultViews, getAutomations, getDatabase, getDatabases, getFields, getRecords, getViews, updateAutomation, updateDatabase, updateField, updateRecord, updateView } from '../lib/data'
import type { AutomationActionType, AutomationTriggerType, Database, DatabaseAutomation, DatabaseView, Field, FieldType, RecordRow, ViewType } from '../types'

type FilterRule={id:string;fieldId:string;op:'equals'|'not_equals'|'contains'|'empty'|'not_empty';value:string}
type SortRule={id:string;fieldId:string;direction:'asc'|'desc'}
type ViewConfig={hiddenFields:string[];fieldOrder:string[];columnWidths:Record<string,number>;rowHeights:Record<string,number>;rowOrder:string[];filters:FilterRule[];sorts:SortRule[];groupFieldId?:string;density?:'compact'|'comfortable'|'roomy';wrap?:boolean;gallerySize?:'small'|'medium'|'large'}
type OptionColors=Record<string,string>

const FIELD_TYPES:Array<{value:FieldType;label:string;hint:string}>=[
 {value:'text',label:'Text',hint:'Names and short notes'},
 {value:'long_text',label:'Long text',hint:'Descriptions and notes'},
 {value:'number',label:'Number',hint:'Counts, ratings and money'},
 {value:'select',label:'Select',hint:'One category or label'},
 {value:'multi_select',label:'Multi-select',hint:'Tags and multiple categories'},
 {value:'status',label:'Status',hint:'A workflow stage'},
 {value:'date',label:'Date',hint:'Dates and deadlines'},
 {value:'checkbox',label:'Checkbox',hint:'Yes or no'},
 {value:'url',label:'URL',hint:'A web link'},
 {value:'email',label:'Email',hint:'Email address'},
 {value:'phone',label:'Phone',hint:'Phone number'},
 {value:'image',label:'Image',hint:'A single image URL'},
 {value:'files',label:'Files & media',hint:'Multiple file or image URLs'},
 {value:'relation',label:'Relation',hint:'Connect another database'},
 {value:'created_time',label:'Created time',hint:'Automatic, read only'},
 {value:'last_edited_time',label:'Last edited time',hint:'Automatic, read only'},
]
const DEFAULT_TAG_COLORS=['#e8e4dc','#dce9df','#eadfef','#dce9ee','#f1e1d5','#e5e2f0','#f3dfdf','#eee3c8']

const emptyConfig=():ViewConfig=>({hiddenFields:[],fieldOrder:[],columnWidths:{},rowHeights:{},rowOrder:[],filters:[],sorts:[],density:'comfortable',wrap:false,gallerySize:'medium'})
const normalizeConfig=(raw:Record<string,unknown>|undefined):ViewConfig=>{const base=emptyConfig();return {...base,...(raw||{}),hiddenFields:Array.isArray(raw?.hiddenFields)?raw!.hiddenFields as string[]:[],fieldOrder:Array.isArray(raw?.fieldOrder)?raw!.fieldOrder as string[]:[],columnWidths:typeof raw?.columnWidths==='object'&&raw?.columnWidths?raw.columnWidths as Record<string,number>:{},rowHeights:typeof raw?.rowHeights==='object'&&raw?.rowHeights?raw.rowHeights as Record<string,number>:{},rowOrder:Array.isArray(raw?.rowOrder)?raw!.rowOrder as string[]:[],filters:Array.isArray(raw?.filters)?raw!.filters as FilterRule[]:[],sorts:Array.isArray(raw?.sorts)?raw!.sorts as SortRule[]:[]}}

function useOutsideClose<T extends HTMLElement>(open:boolean,onClose:()=>void){const ref=useRef<T>(null);useEffect(()=>{if(!open)return;const handler=(event:MouseEvent)=>{const node=ref.current;if(node&&!node.contains(event.target as Node))onClose()};document.addEventListener('mousedown',handler);return()=>document.removeEventListener('mousedown',handler)},[open,onClose]);return ref}

export default function DatabaseWorkspace(){
 const{databaseId=''}=useParams();const{workspace}=useAppContext()
 const[database,setDatabase]=useState<Database|null>(null),[databases,setDatabases]=useState<Database[]>([]),[fields,setFields]=useState<Field[]>([]),[records,setRecords]=useState<RecordRow[]>([]),[views,setViews]=useState<DatabaseView[]>([]),[activeViewId,setActiveViewId]=useState(''),[automations,setAutomations]=useState<DatabaseAutomation[]>([]),[automationsAvailable,setAutomationsAvailable]=useState(true),[relatedRecords,setRelatedRecords]=useState<Record<string,RecordRow[]>>({}),[query,setQuery]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState(''),[settingsOpen,setSettingsOpen]=useState(false),[addingView,setAddingView]=useState(false),[addingField,setAddingField]=useState(false),[automationOpen,setAutomationOpen]=useState(false)
 const load=async()=>{setError('');try{const[db,allDbs,nextFields,nextRecords]=await Promise.all([getDatabase(databaseId),getDatabases(workspace.id),getFields(databaseId),getRecords(databaseId)]);let nextViews=await ensureDefaultViews(databaseId);if(!nextViews?.length)nextViews=await getViews(databaseId);setDatabase(db);setDatabases(allDbs);setFields(nextFields);setRecords(nextRecords);setViews(nextViews||[]);setActiveViewId(current=>(nextViews||[]).some(v=>v.id===current)?current:(nextViews?.[0]?.id||''));try{setAutomations(await getAutomations(databaseId));setAutomationsAvailable(true)}catch{setAutomations([]);setAutomationsAvailable(false)}}catch(e){setError(e instanceof Error?e.message:String(e))}}
 useEffect(()=>{void load()},[databaseId,workspace.id])
 useEffect(()=>{const targets=[...new Set(fields.filter(f=>f.type==='relation').map(f=>String(f.config?.target_database_id||'')).filter(Boolean))];let cancelled=false;(async()=>{const entries=await Promise.all(targets.map(async id=>{try{return[id,await getRecords(id)]as const}catch{return[id,[]]as const}}));if(!cancelled)setRelatedRecords(Object.fromEntries(entries))})();return()=>{cancelled=true}},[fields])
 const schemaFields=useMemo(()=>fields.filter(f=>f.name.trim().toLowerCase()!=='name').sort((a,b)=>a.position-b.position),[fields])
 const activeView=views.find(v=>v.id===activeViewId)||views[0]
 const config=normalizeConfig(activeView?.config)
 const orderedFields=useMemo(()=>{const map=new Map(schemaFields.map(f=>[f.id,f]));const ordered=config.fieldOrder.map(id=>map.get(id)).filter(Boolean) as Field[];schemaFields.forEach(f=>{if(!ordered.some(x=>x.id===f.id))ordered.push(f)});return ordered},[schemaFields,config.fieldOrder.join('|')])
 const visibleFields=orderedFields.filter(f=>!config.hiddenFields.includes(f.id))
 const displayedRecords=useMemo(()=>{let next=[...records];const q=query.trim().toLowerCase();if(q)next=next.filter(r=>r.title.toLowerCase().includes(q)||schemaFields.some(f=>formatValue(valueForField(r,f)).toLowerCase().includes(q)));next=next.filter(r=>config.filters.every(rule=>matchesFilter(r,rule,schemaFields)));if(config.sorts.length){next.sort((a,b)=>{for(const rule of config.sorts){const field=schemaFields.find(f=>f.id===rule.fieldId);const av=rule.fieldId==='__title__'?a.title:field?valueForField(a,field):'',bv=rule.fieldId==='__title__'?b.title:field?valueForField(b,field):'';const c=compare(av,bv);if(c)return c*(rule.direction==='desc'?-1:1)}return 0})}else if(config.rowOrder.length){const order=new Map(config.rowOrder.map((id,i)=>[id,i]));next.sort((a,b)=>(order.get(a.id)??999999)-(order.get(b.id)??999999)||a.created_at.localeCompare(b.created_at))}return next},[records,query,schemaFields,JSON.stringify(config.filters),JSON.stringify(config.sorts),config.rowOrder.join('|')])
 const saveViewConfig=async(patch:Partial<ViewConfig>)=>{if(!activeView)return;const next={...normalizeConfig(activeView.config),...patch};setViews(v=>v.map(x=>x.id===activeView.id?{...x,config:next}:x));try{await updateView(activeView.id,{config:next})}catch(e){setError(e instanceof Error?e.message:String(e))}}
 const previewViewConfig=(patch:Partial<ViewConfig>)=>{if(!activeView)return;const next={...normalizeConfig(activeView.config),...patch};setViews(v=>v.map(x=>x.id===activeView.id?{...x,config:next}:x))}
 const runAutomations=async(record:RecordRow,event:{type:'record_created'|'field_changed';fieldId?:string;value?:unknown})=>{if(!automationsAvailable)return record;let current=record;for(const rule of automations.filter(a=>a.enabled&&a.trigger_type===event.type)){if(event.type==='field_changed'){const triggerField=String(rule.trigger_config?.field_id||'');if(triggerField&&triggerField!==event.fieldId)continue;const expected=rule.trigger_config?.equals;if(expected!==undefined&&expected!==''&&String(event.value??'')!==String(expected))continue}const target=String(rule.action_config?.field_id||'');if(!target)continue;let value:unknown=rule.action_config?.value;if(rule.action_type==='set_today')value=new Date().toISOString().slice(0,10);if(rule.action_type==='set_checkbox')value=Boolean(rule.action_config?.value);const data={...current.data,[target]:value};current=await updateRecord(current.id,{data})}return current}
 const addRecord=async()=>{setBusy(true);try{let created=await createRecord(databaseId,'Untitled');created=await runAutomations(created,{type:'record_created'});setRecords(v=>[...v,created]);if(activeView&&!config.sorts.length)await saveViewConfig({rowOrder:[...config.rowOrder.filter(id=>id!==created.id),created.id]})}catch(e){setError(e instanceof Error?e.message:String(e))}finally{setBusy(false)}}
 const saveRecord=async(record:RecordRow,patch:{title?:string;fieldId?:string;value?:unknown})=>{const nextData=patch.fieldId?{...record.data,[patch.fieldId]:patch.value}:record.data;const optimistic={...record,title:patch.title??record.title,data:nextData};setRecords(v=>v.map(r=>r.id===record.id?optimistic:r));try{let updated=await updateRecord(record.id,{...(patch.title!==undefined?{title:patch.title}:{}),...(patch.fieldId?{data:nextData}:{})});if(patch.fieldId)updated=await runAutomations(updated,{type:'field_changed',fieldId:patch.fieldId,value:patch.value});setRecords(v=>v.map(r=>r.id===record.id?updated:r))}catch(e){setError(e instanceof Error?e.message:String(e));void load()}}
 const removeRecord=async(record:RecordRow)=>{if(!window.confirm(`Delete “${record.title}”?`))return;await deleteRecord(record.id);setRecords(v=>v.filter(r=>r.id!==record.id));if(config.rowOrder.includes(record.id))void saveViewConfig({rowOrder:config.rowOrder.filter(id=>id!==record.id)})}
 const renameDatabase=async(name:string)=>{const clean=name.trim();if(!clean||!database||clean===database.name)return;setDatabase({...database,name:clean});try{await updateDatabase(database.id,{name:clean});window.dispatchEvent(new Event('atlas-workspace-changed'))}catch(e){setError(e instanceof Error?e.message:String(e));void load()}}
 const addView=async(name:string,type:ViewType)=>{const created=await createView(databaseId,name||capitalize(type),type,views.length);setViews(v=>[...v,created]);setActiveViewId(created.id);setAddingView(false)}
 const changeViewType=async(type:ViewType)=>{if(!activeView)return;const updated=await updateView(activeView.id,{type});setViews(v=>v.map(x=>x.id===updated.id?updated:x))}
 const removeView=async()=>{if(!activeView||views.length<=1)return;if(!window.confirm(`Delete view “${activeView.name}”? The database records will not be deleted.`))return;await deleteView(activeView.id);const next=views.filter(v=>v.id!==activeView.id);setViews(next);setActiveViewId(next[0]?.id||'')}
 const renameView=async(name:string)=>{if(!activeView||!name.trim())return;const updated=await updateView(activeView.id,{name:name.trim()});setViews(v=>v.map(x=>x.id===updated.id?updated:x))}
 const reorderFields=async(sourceId:string,targetId:string)=>{if(sourceId===targetId)return;const list=[...orderedFields];const from=list.findIndex(f=>f.id===sourceId),to=list.findIndex(f=>f.id===targetId);if(from<0||to<0)return;const[moved]=list.splice(from,1);list.splice(to,0,moved);await saveViewConfig({fieldOrder:list.map(f=>f.id)})}
 const reorderRecords=async(sourceId:string,targetId:string)=>{if(sourceId===targetId||config.sorts.length)return;const base=config.rowOrder.length?config.rowOrder.filter(id=>records.some(r=>r.id===id)):displayedRecords.map(r=>r.id);records.forEach(r=>{if(!base.includes(r.id))base.push(r.id)});const from=base.indexOf(sourceId),to=base.indexOf(targetId);if(from<0||to<0)return;const[moved]=base.splice(from,1);base.splice(to,0,moved);await saveViewConfig({rowOrder:base})}
 if(error&&!database)return <div className="db-workspace-error"><h2>Atlas could not open this collection</h2><p>{error}</p></div>
 if(!database||!activeView)return <div className="db-workspace-loading">Opening collection…</div>
 return <div className="database-workspace">
  <header className="database-workspace-head"><div><span>DATABASE</span><DatabaseName value={database.name} onSave={renameDatabase}/><p>{records.length} record{records.length===1?'':'s'} · {schemaFields.length+1} properties</p></div><div className="database-workspace-head-actions"><Link className="db-page-link" to={`/database/${database.id}/page`}><Sparkles/>Design HQ</Link><button className="db-primary" onClick={()=>void addRecord()} disabled={busy}><Plus/>New</button></div></header>
  <div className="db-view-bar"><div className="db-saved-views">{views.map(view=><button key={view.id} className={view.id===activeView.id?'active':''} onClick={()=>setActiveViewId(view.id)}>{view.type==='table'?<Table2/>:view.type==='gallery'?<LayoutGrid/>:<KanbanSquare/>}{view.name}</button>)}<button className="db-add-view" onMouseDown={e=>e.stopPropagation()} onClick={()=>setAddingView(v=>!v)}><Plus/></button>{addingView&&<NewViewPopover onAdd={addView} onClose={()=>setAddingView(false)}/>}</div><div className="db-view-actions"><button title="Filter" className={config.filters.length?'active':''} onClick={()=>setSettingsOpen(true)}><Filter/><span>{config.filters.length||''}</span></button><button title="Automations" className={automations.length?'active':''} onClick={()=>setAutomationOpen(true)}><Bolt/><span>{automations.length||''}</span></button><button title="View settings" onClick={()=>setSettingsOpen(v=>!v)}><Settings2/></button></div></div>
  <div className="database-workspace-toolbar"><div className="db-search"><Search/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder={`Search ${database.name}`}/></div><button className="db-inline-add-field-button" onMouseDown={e=>e.stopPropagation()} onClick={()=>setAddingField(true)}><Plus/>Property</button></div>
  {error&&<div className="db-inline-error">{error}</div>}
  <div className="database-workspace-body">{activeView.type==='table'?<DatabaseTable database={database} databases={databases} records={displayedRecords} fields={visibleFields} allFields={schemaFields} relatedRecords={relatedRecords} config={config} sorted={Boolean(config.sorts.length)} addingField={addingField} onAddingField={setAddingField} onSave={saveRecord} onDelete={removeRecord} onAdd={addRecord} onChanged={load} onReorderFields={reorderFields} onReorderRecords={reorderRecords} onViewConfig={saveViewConfig} onPreviewConfig={previewViewConfig}/>:activeView.type==='gallery'?<DatabaseGallery database={database} records={displayedRecords} fields={visibleFields} config={config}/>:<DatabaseBoard database={database} records={displayedRecords} fields={visibleFields} groupFieldId={config.groupFieldId||''} onGroupField={id=>void saveViewConfig({groupFieldId:id})} onSave={saveRecord}/>}</div>
  {settingsOpen&&<ViewSettings view={activeView} fields={schemaFields} config={config} onClose={()=>setSettingsOpen(false)} onRename={renameView} onType={changeViewType} onConfig={saveViewConfig} onDelete={removeView}/>} 
  {automationOpen&&<AutomationPanel database={database} fields={schemaFields} automations={automations} available={automationsAvailable} onClose={()=>setAutomationOpen(false)} onChanged={async()=>{try{setAutomations(await getAutomations(database.id));setAutomationsAvailable(true)}catch{setAutomationsAvailable(false)}}}/>} 
 </div>
}

function DatabaseName({value,onSave}:{value:string;onSave:(name:string)=>void}){const[local,setLocal]=useState(value);useEffect(()=>setLocal(value),[value]);return <input className="db-inline-name" value={local} onChange={e=>setLocal(e.target.value)} onBlur={()=>onSave(local)} onKeyDown={e=>{if(e.key==='Enter')e.currentTarget.blur();if(e.key==='Escape'){setLocal(value);e.currentTarget.blur()}}}/>}

function NewViewPopover({onAdd,onClose}:{onAdd:(name:string,type:ViewType)=>void;onClose:()=>void}){const[type,setType]=useState<ViewType>('table'),[name,setName]=useState('');const ref=useOutsideClose<HTMLDivElement>(true,onClose);return <div ref={ref} className="db-popover db-new-view-popover"><strong>New view</strong><input autoFocus value={name} onChange={e=>setName(e.target.value)} placeholder="View name"/><div className="db-layout-choices"><button className={type==='table'?'active':''} onClick={()=>setType('table')}><Table2/>Table</button><button className={type==='gallery'?'active':''} onClick={()=>setType('gallery')}><LayoutGrid/>Gallery</button><button className={type==='board'?'active':''} onClick={()=>setType('board')}><KanbanSquare/>Board</button></div><div className="db-popover-actions"><button onClick={onClose}>Cancel</button><button className="primary" onClick={()=>onAdd(name||capitalize(type),type)}>Create</button></div></div>}

function DatabaseTable({database,databases,records,fields,allFields,relatedRecords,config,sorted,addingField,onAddingField,onSave,onDelete,onAdd,onChanged,onReorderFields,onReorderRecords,onViewConfig,onPreviewConfig}:{database:Database;databases:Database[];records:RecordRow[];fields:Field[];allFields:Field[];relatedRecords:Record<string,RecordRow[]>;config:ViewConfig;sorted:boolean;addingField:boolean;onAddingField:(v:boolean)=>void;onSave:(r:RecordRow,p:{title?:string;fieldId?:string;value?:unknown})=>void;onDelete:(r:RecordRow)=>void;onAdd:()=>void;onChanged:()=>Promise<void>;onReorderFields:(s:string,t:string)=>Promise<void>;onReorderRecords:(s:string,t:string)=>Promise<void>;onViewConfig:(patch:Partial<ViewConfig>)=>Promise<void>;onPreviewConfig:(patch:Partial<ViewConfig>)=>void}){
 const dragField=useRef(''),dragRecord=useRef('');const baseHeight=config.density==='compact'?30:config.density==='roomy'?58:40;const titleWidth=config.columnWidths.__title__||240
 const rowResize=(recordId:string,height:number)=><RowResizer height={height} onPreview={h=>onPreviewConfig({rowHeights:{...config.rowHeights,[recordId]:h}})} onCommit={h=>void onViewConfig({rowHeights:{...config.rowHeights,[recordId]:h}})}/>
 return <div className={`db-sheet-wrap ${config.wrap?'wrap':''}`}><table className="db-sheet"><thead><tr><th className="db-row-index">#</th><th className="db-title-column" style={{width:titleWidth,minWidth:titleWidth}}><button className="db-built-in-header"><span><strong>Title</strong><small>Title</small></span></button><ColumnResizer width={titleWidth} onPreview={w=>onPreviewConfig({columnWidths:{...config.columnWidths,__title__:w}})} onCommit={w=>void onViewConfig({columnWidths:{...config.columnWidths,__title__:w}})}/></th>{fields.map(field=>{const width=config.columnWidths[field.id]||170;return <FieldHeader key={field.id} field={field} databases={databases} width={width} onChanged={onChanged} onFilter={(op)=>void onViewConfig({filters:[...config.filters,{id:crypto.randomUUID(),fieldId:field.id,op,value:''}]})} onSort={direction=>void onViewConfig({sorts:[{id:crypto.randomUUID(),fieldId:field.id,direction}]})} onHide={()=>void onViewConfig({hiddenFields:[...new Set([...config.hiddenFields,field.id])]})} onInsert={async side=>{const pos=Math.max(1,field.position+(side==='right'?1:0));await createField(database.id,{name:'New property',type:'text',required:false,config:{}},pos);await onChanged()}} onDuplicate={async()=>{await createField(database.id,{name:`${field.name} copy`,type:field.type,required:field.required,config:field.config},allFields.length+1);await onChanged()}} onDragStart={()=>{dragField.current=field.id}} onDrop={()=>void onReorderFields(dragField.current,field.id)} onResizePreview={w=>onPreviewConfig({columnWidths:{...config.columnWidths,[field.id]:w}})} onResizeCommit={w=>void onViewConfig({columnWidths:{...config.columnWidths,[field.id]:w}})}/>})}<th className="db-add-field-column">{addingField?<FieldCreator database={database} databases={databases} position={allFields.length+1} onCancel={()=>onAddingField(false)} onAdded={async()=>{onAddingField(false);await onChanged()}}/>:<button onClick={()=>onAddingField(true)}><Plus/>Property</button>}</th><th className="db-actions-column"/></tr></thead><tbody>{records.map((record,index)=>{const height=config.rowHeights[record.id]||baseHeight;return <tr key={record.id} onDragOver={e=>{if(!sorted)e.preventDefault()}} onDrop={()=>void onReorderRecords(dragRecord.current,record.id)} style={{height}} className={!sorted?'db-draggable-row':''}><td className="db-row-index">{!sorted?<span className="db-row-drag-handle" draggable onDragStart={()=>{dragRecord.current=record.id}} title="Drag to move row"><GripVertical/></span>:index+1}{rowResize(record.id,height)}</td><td className="db-title-column" style={{width:titleWidth,minWidth:titleWidth}}><input value={record.title} onChange={e=>onSave(record,{title:e.target.value})}/><Link title="Open record" to={`/database/${database.id}/record/${record.id}`}><ExternalLink/></Link>{rowResize(record.id,height)}</td>{fields.map(field=><td key={field.id} style={{width:config.columnWidths[field.id]||170,minWidth:config.columnWidths[field.id]||170}}><CellEditor field={field} record={record} value={valueForField(record,field)} relationRecords={relatedRecords[String(field.config?.target_database_id||'')]||[]} onChange={value=>onSave(record,{fieldId:field.id,value})}/>{rowResize(record.id,height)}</td>)}<td className="db-add-field-column db-empty-column">{rowResize(record.id,height)}</td><td className="db-actions-column"><button title="Delete record" onClick={()=>void onDelete(record)}><Trash2/></button>{rowResize(record.id,height)}</td></tr>})}</tbody></table><button className="db-add-row" onClick={()=>void onAdd()}><Plus/>New record</button></div>
}

function ColumnResizer({width,onPreview,onCommit}:{width:number;onPreview:(width:number)=>void;onCommit:(width:number)=>void}){return <span className="db-column-resizer" title="Drag to resize column" onPointerDown={e=>{e.preventDefault();e.stopPropagation();const start=e.clientX,startWidth=width;let latest=width;document.body.classList.add('db-resizing-column');const move=(ev:PointerEvent)=>{latest=Math.max(28,startWidth+ev.clientX-start);onPreview(latest)};const up=()=>{document.body.classList.remove('db-resizing-column');window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up);onCommit(latest)};window.addEventListener('pointermove',move);window.addEventListener('pointerup',up)}} onDoubleClick={e=>{e.stopPropagation();onCommit(170)}}/>}
function RowResizer({height,onPreview,onCommit}:{height:number;onPreview:(height:number)=>void;onCommit:(height:number)=>void}){return <span className="db-row-resizer" title="Drag to resize row" onPointerDown={e=>{e.preventDefault();e.stopPropagation();const start=e.clientY,startHeight=height;let latest=height;document.body.classList.add('db-resizing-row');const move=(ev:PointerEvent)=>{latest=Math.max(18,startHeight+ev.clientY-start);onPreview(latest)};const up=()=>{document.body.classList.remove('db-resizing-row');window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up);onCommit(latest)};window.addEventListener('pointermove',move);window.addEventListener('pointerup',up)}}/>}

function FieldHeader({field,databases,width,onChanged,onFilter,onSort,onHide,onInsert,onDuplicate,onDragStart,onDrop,onResizePreview,onResizeCommit}:{field:Field;databases:Database[];width:number;onChanged:()=>Promise<void>;onFilter:(op:FilterRule['op'])=>void;onSort:(direction:'asc'|'desc')=>void;onHide:()=>void;onInsert:(side:'left'|'right')=>Promise<void>;onDuplicate:()=>Promise<void>;onDragStart:()=>void;onDrop:()=>void;onResizePreview:(w:number)=>void;onResizeCommit:(w:number)=>void}){const[open,setOpen]=useState(false),[editing,setEditing]=useState(false);const ref=useOutsideClose<HTMLTableCellElement>(open,()=>{setOpen(false);setEditing(false)});return <th ref={ref} className="db-field-header" style={{width,minWidth:width}} draggable={!open} onDragStart={onDragStart} onDragOver={e=>e.preventDefault()} onDrop={onDrop}><button className="db-field-header-summary" onClick={()=>setOpen(v=>!v)}><GripVertical/><PropertyIcon type={field.type}/><span><strong>{field.name}</strong></span><ChevronDown/></button><ColumnResizer width={width} onPreview={onResizePreview} onCommit={onResizeCommit}/>{open&&<div className="db-popover db-property-menu">{editing?<PropertyEditor field={field} databases={databases} onCancel={()=>setEditing(false)} onSaved={async()=>{setEditing(false);setOpen(false);await onChanged()}}/>:<><button onClick={()=>setEditing(true)}><Settings2/>Edit property<ChevronRight/></button><button onClick={()=>{onSort('asc');setOpen(false)}}><ArrowUp/>Sort ascending</button><button onClick={()=>{onSort('desc');setOpen(false)}}><ArrowDown/>Sort descending</button><button onClick={()=>{onFilter('equals');setOpen(false)}}><Filter/>Filter by this property</button><button onClick={()=>{onHide();setOpen(false)}}><EyeOff/>Hide in this view</button><div className="db-menu-separator"/><button onClick={()=>void onInsert('left')}><Plus/>Insert left</button><button onClick={()=>void onInsert('right')}><Plus/>Insert right</button><button onClick={()=>void onDuplicate()}><Copy/>Duplicate property</button><button className="danger" onClick={async()=>{if(!window.confirm(`Delete “${field.name}” from this database?`))return;await deleteField(field.id);setOpen(false);await onChanged()}}><Trash2/>Delete property</button></>}</div>}</th>}

function PropertyEditor({field,databases,onCancel,onSaved}:{field:Field;databases:Database[];onCancel:()=>void;onSaved:()=>Promise<void>}){const[name,setName]=useState(field.name),[type,setType]=useState<FieldType>(field.type),[options,setOptions]=useState(optionStrings(field).join('\n')),[colors,setColors]=useState<OptionColors>(optionColorMap(field)),[target,setTarget]=useState(String(field.config?.target_database_id||'')),[required,setRequired]=useState(field.required);const currentOptions=splitOptions(options);const save=async()=>{const config={...field.config,...(['select','multi_select','status'].includes(type)?{options:currentOptions,optionColors:cleanOptionColors(currentOptions,colors)}:{}),...(type==='relation'?{target_database_id:target}:{})};await updateField(field.id,{name:name.trim()||field.name,type,required,config});await onSaved()};return <div className="db-property-editor"><input autoFocus value={name} onChange={e=>setName(e.target.value)}/><label>Type<FieldTypePicker value={type} onChange={setType}/></label>{['select','multi_select','status'].includes(type)&&<><label>Options<textarea value={options} onChange={e=>setOptions(e.target.value)} placeholder={'One option per line\nIdea\nIn progress\nDone'}/></label><OptionColorEditor options={currentOptions} colors={colors} onChange={setColors}/></>}{type==='relation'&&<label>Database<select value={target} onChange={e=>setTarget(e.target.value)}><option value="">Choose database…</option>{databases.map(db=><option key={db.id} value={db.id}>{db.name}</option>)}</select></label>}<label className="db-check-row"><input type="checkbox" checked={required} onChange={e=>setRequired(e.target.checked)}/>Required</label><div className="db-popover-actions"><button onClick={onCancel}>Cancel</button><button className="primary" onClick={()=>void save()}>Save</button></div></div>}

function FieldCreator({database,databases,position,onCancel,onAdded}:{database:Database;databases:Database[];position:number;onCancel:()=>void;onAdded:()=>Promise<void>}){const[name,setName]=useState(''),[type,setType]=useState<FieldType>('text'),[options,setOptions]=useState(''),[colors,setColors]=useState<OptionColors>({}),[target,setTarget]=useState(''),[busy,setBusy]=useState(false);const currentOptions=splitOptions(options);const ref=useOutsideClose<HTMLDivElement>(true,onCancel);const add=async()=>{if(!name.trim())return;setBusy(true);try{const config={...(['select','multi_select','status'].includes(type)?{options:currentOptions,optionColors:cleanOptionColors(currentOptions,colors)}:{}),...(type==='relation'?{target_database_id:target}:{})};await createField(database.id,{name:name.trim(),type,required:false,config},position);await onAdded()}finally{setBusy(false)}};return <div ref={ref} className="db-popover db-field-creator"><strong>New property</strong><input autoFocus value={name} onChange={e=>setName(e.target.value)} placeholder="Property name"/><FieldTypePicker value={type} onChange={setType}/>{['select','multi_select','status'].includes(type)&&<><textarea value={options} onChange={e=>setOptions(e.target.value)} placeholder={'Options, one per line\nIdea\nIn progress\nDone'}/><OptionColorEditor options={currentOptions} colors={colors} onChange={setColors}/></>} {type==='relation'&&<select value={target} onChange={e=>setTarget(e.target.value)}><option value="">Choose database…</option>{databases.map(db=><option key={db.id} value={db.id}>{db.name}</option>)}</select>}<div className="db-popover-actions"><button onClick={onCancel}>Cancel</button><button className="primary" disabled={busy||!name.trim()} onClick={()=>void add()}>Add property</button></div></div>}

function FieldTypePicker({value,onChange}:{value:FieldType;onChange:(value:FieldType)=>void}){const[open,setOpen]=useState(false),[search,setSearch]=useState('');const ref=useOutsideClose<HTMLDivElement>(open,()=>setOpen(false));const current=FIELD_TYPES.find(type=>type.value===value)||FIELD_TYPES[0];const filtered=FIELD_TYPES.filter(type=>(type.label+' '+type.hint).toLowerCase().includes(search.toLowerCase()));return <div ref={ref} className="db-type-picker"><button type="button" className="db-type-picker-trigger" onClick={()=>setOpen(v=>!v)}><PropertyIcon type={current.value}/><span><strong>{current.label}</strong><small>{current.hint}</small></span><ChevronDown/></button>{open&&<div className="db-popover db-type-menu"><input autoFocus value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search property types…"/>{filtered.map(type=><button type="button" key={type.value} className={type.value===value?'active':''} onClick={()=>{onChange(type.value);setOpen(false)}}><PropertyIcon type={type.value}/><span><strong>{type.label}</strong><small>{type.hint}</small></span>{type.value===value&&<Check/>}</button>)}</div>}</div>}

function OptionColorEditor({options,colors,onChange}:{options:string[];colors:OptionColors;onChange:(colors:OptionColors)=>void}){if(!options.length)return null;return <div className="db-option-colors"><span>Tag colors</span>{options.map((option,index)=>{const color=colors[option]||DEFAULT_TAG_COLORS[index%DEFAULT_TAG_COLORS.length];return <label key={option}><span className="db-tag" style={tagStyle(color)}>{option}</span><input type="color" value={normalizeHex(color)} onChange={e=>onChange({...colors,[option]:e.target.value})}/><input className="db-color-value" value={color} onChange={e=>onChange({...colors,[option]:e.target.value})}/></label>})}</div>}

function CellEditor({field,record,value,relationRecords,onChange}:{field:Field;record:RecordRow;value:unknown;relationRecords:RecordRow[];onChange:(value:unknown)=>void}){if(field.type==='created_time'||field.type==='last_edited_time')return <span className="db-readonly-time">{formatDate(field.type==='created_time'?record.created_at:record.updated_at)}</span>;if(field.type==='checkbox')return <input className="db-cell-check" type="checkbox" checked={Boolean(value)} onChange={e=>onChange(e.target.checked)}/>;if(field.type==='date')return <input className="db-cell-input" type="date" value={String(value??'')} onChange={e=>onChange(e.target.value)}/>;if(field.type==='number')return <input className="db-cell-input" type="number" value={value===null||value===undefined?'':String(value)} onChange={e=>onChange(e.target.value===''?null:Number(e.target.value))}/>;if(field.type==='select'||field.type==='status')return <TagPicker options={optionStrings(field)} colors={optionColorMap(field)} selected={value?[String(value)]:[]} single status={field.type==='status'} onChange={v=>onChange(v[0]||'')}/>;if(field.type==='multi_select')return <TagPicker options={optionStrings(field)} colors={optionColorMap(field)} selected={Array.isArray(value)?value.map(String):[]} onChange={onChange}/>;if(field.type==='relation')return <RelationPicker records={relationRecords} selected={String(value??'')} onChange={onChange}/>;if(field.type==='long_text')return <textarea className="db-cell-input db-cell-textarea" value={String(value??'')} onChange={e=>onChange(e.target.value)}/>;if(field.type==='files')return <input className="db-cell-input" value={Array.isArray(value)?value.join(', '):String(value??'')} placeholder="Paste file URLs" onChange={e=>onChange(e.target.value.split(',').map(x=>x.trim()).filter(Boolean))}/>;if(field.type==='image')return <input className="db-cell-input" value={String(value??'')} placeholder="Image URL" onChange={e=>onChange(e.target.value)}/>;return <input className="db-cell-input" type={field.type==='url'?'url':field.type==='email'?'email':field.type==='phone'?'tel':'text'} value={String(value??'')} onChange={e=>onChange(e.target.value)}/>}

function TagPicker({options,colors,selected,onChange,single=false,status=false}:{options:string[];colors:OptionColors;selected:string[];onChange:(values:string[])=>void;single?:boolean;status?:boolean}){const[open,setOpen]=useState(false),[search,setSearch]=useState('');const ref=useOutsideClose<HTMLDivElement>(open,()=>setOpen(false));const filtered=options.filter(o=>o.toLowerCase().includes(search.toLowerCase()));return <div ref={ref} className="db-tag-picker"><button className="db-tag-display" onClick={()=>setOpen(v=>!v)}>{selected.length?selected.map(s=>{const i=Math.max(0,options.indexOf(s));const color=colors[s]||DEFAULT_TAG_COLORS[i%DEFAULT_TAG_COLORS.length];return <span className={`db-tag ${status?'status':''}`} style={tagStyle(color)} key={s}>{status&&<i/>}{s}</span>}):<span className="db-cell-placeholder">Empty</span>}</button>{open&&<div className="db-popover db-option-picker"><input autoFocus value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search options…"/>{filtered.map(o=>{const i=Math.max(0,options.indexOf(o));const color=colors[o]||DEFAULT_TAG_COLORS[i%DEFAULT_TAG_COLORS.length];return <button key={o} onClick={()=>{if(single){onChange([o]);setOpen(false)}else onChange(selected.includes(o)?selected.filter(x=>x!==o):[...selected,o])}}><span className="db-tag" style={tagStyle(color)}>{o}</span>{selected.includes(o)&&<Check/>}</button>})}{!options.length&&<small>Add options from the property menu.</small>}{single&&selected.length>0&&<button onClick={()=>{onChange([]);setOpen(false)}}>Clear</button>}</div>}</div>}
function RelationPicker({records,selected,onChange}:{records:RecordRow[];selected:string;onChange:(value:string)=>void}){const[open,setOpen]=useState(false),[search,setSearch]=useState('');const ref=useOutsideClose<HTMLDivElement>(open,()=>setOpen(false));const current=records.find(r=>r.id===selected);return <div ref={ref} className="db-relation-picker"><button onClick={()=>setOpen(v=>!v)}>{current?<><span className="db-record-icon">▧</span>{current.title}</>:<span className="db-cell-placeholder">Empty</span>}</button>{open&&<div className="db-popover db-option-picker"><input autoFocus value={search} onChange={e=>setSearch(e.target.value)} placeholder="Find a record…"/><button onClick={()=>{onChange('');setOpen(false)}}>None</button>{records.filter(r=>r.title.toLowerCase().includes(search.toLowerCase())).map(r=><button key={r.id} onClick={()=>{onChange(r.id);setOpen(false)}}>{r.title}{r.id===selected&&<Check/>}</button>)}</div>}</div>}

function DatabaseGallery({database,records,fields,config}:{database:Database;records:RecordRow[];fields:Field[];config:ViewConfig}){return <div className={`db-native-gallery size-${config.gallerySize||'medium'}`}>{records.map(record=><Link key={record.id} to={`/database/${database.id}/record/${record.id}`} className="db-native-card"><strong>{record.title}</strong>{fields.slice(0,6).map(field=>{const value=formatValue(valueForField(record,field));return value?<span key={field.id}><small>{field.name}</small>{value}</span>:null})}</Link>)}</div>}
function DatabaseBoard({database,records,fields,groupFieldId,onGroupField,onSave}:{database:Database;records:RecordRow[];fields:Field[];groupFieldId:string;onGroupField:(id:string)=>void;onSave:(r:RecordRow,p:{fieldId?:string;value?:unknown})=>void}){const boardFields=fields.filter(f=>['select','status','checkbox'].includes(f.type));const field=fields.find(f=>f.id===groupFieldId)||boardFields[0];const drag=useRef('');if(!field)return <div className="db-board-empty"><KanbanSquare/><strong>Choose a Status, Select, or Checkbox property to create lanes.</strong>{boardFields.length>0&&<select onChange={e=>onGroupField(e.target.value)}>{boardFields.map(f=><option key={f.id} value={f.id}>{f.name}</option>)}</select>}</div>;const values=field.type==='checkbox'?['Unchecked','Checked']:[...optionStrings(field),'No value'];const drop=(lane:string)=>{const record=records.find(r=>r.id===drag.current);if(!record)return;const value=field.type==='checkbox'?lane==='Checked':lane==='No value'?'':lane;onSave(record,{fieldId:field.id,value})};return <div className="db-board-shell"><div className="db-board-controls"><span>Group by</span><select value={field.id} onChange={e=>onGroupField(e.target.value)}>{boardFields.map(f=><option key={f.id} value={f.id}>{f.name}</option>)}</select></div><div className="db-native-board">{values.map(lane=>{const laneRecords=records.filter(r=>{const raw=valueForField(r,field);if(field.type==='checkbox')return(Boolean(raw)?'Checked':'Unchecked')===lane;if(lane==='No value')return!raw;return String(raw)===lane});const colors=optionColorMap(field),i=Math.max(0,optionStrings(field).indexOf(lane));return <section key={lane} onDragOver={e=>e.preventDefault()} onDrop={()=>drop(lane)}><header><strong>{field.type==='status'&&lane!=='No value'?<span className="db-tag status" style={tagStyle(colors[lane]||DEFAULT_TAG_COLORS[i%DEFAULT_TAG_COLORS.length])}><i/>{lane}</span>:lane}</strong><span>{laneRecords.length}</span></header>{laneRecords.map(record=><Link draggable onDragStart={()=>{drag.current=record.id}} to={`/database/${database.id}/record/${record.id}`} key={record.id} className="db-board-card"><strong>{record.title}</strong>{fields.filter(f=>f.id!==field.id).slice(0,3).map(f=>{const v=formatValue(valueForField(record,f));return v?<small key={f.id}>{f.name}: {v}</small>:null})}</Link>)}</section>})}</div></div>}

function ViewSettings({view,fields,config,onClose,onRename,onType,onConfig,onDelete}:{view:DatabaseView;fields:Field[];config:ViewConfig;onClose:()=>void;onRename:(name:string)=>Promise<void>;onType:(type:ViewType)=>Promise<void>;onConfig:(patch:Partial<ViewConfig>)=>Promise<void>;onDelete:()=>Promise<void>}){const[name,setName]=useState(view.name),[section,setSection]=useState<'main'|'properties'|'filters'|'sorts'>('main');useEffect(()=>setName(view.name),[view.id,view.name]);const saveName=()=>{if(name.trim()&&name.trim()!==view.name)void onRename(name)};return <aside className="db-settings-panel"><header><div><span>VIEW SETTINGS</span><strong>{section==='main'?view.name:section==='properties'?'Property visibility':section==='filters'?'Filters':'Sorts'}</strong></div><button onClick={onClose}><X/></button></header><div className="db-settings-scroll">{section!=='main'&&<button className="db-back" onClick={()=>setSection('main')}>‹ Back</button>}{section==='main'?<><label className="db-setting-name">View name<input value={name} onChange={e=>setName(e.target.value)} onBlur={saveName}/></label><SettingRow label="Layout" value={capitalize(view.type)} onClick={()=>{}}><select value={view.type} onChange={e=>void onType(e.target.value as ViewType)}><option value="table">Table</option><option value="gallery">Gallery</option><option value="board">Board</option></select></SettingRow><SettingRow label="Property visibility" value={`${fields.length-config.hiddenFields.length} shown`} onClick={()=>setSection('properties')} icon={<Eye/>}/><SettingRow label="Filter" value={config.filters.length?`${config.filters.length} rule${config.filters.length===1?'':'s'}`:'None'} onClick={()=>setSection('filters')} icon={<Filter/>}/><SettingRow label="Sort" value={config.sorts.length?`${config.sorts.length} rule${config.sorts.length===1?'':'s'}`:'Manual'} onClick={()=>setSection('sorts')} icon={<ArrowUp/>}/><label className="db-setting-line"><span>Group</span><select value={config.groupFieldId||''} onChange={e=>void onConfig({groupFieldId:e.target.value})}><option value="">None</option>{fields.filter(f=>['select','status','checkbox'].includes(f.type)).map(f=><option key={f.id} value={f.id}>{f.name}</option>)}</select></label>{view.type==='table'&&<><label className="db-setting-line"><span>Row density</span><select value={config.density||'comfortable'} onChange={e=>void onConfig({density:e.target.value as ViewConfig['density']})}><option value="compact">Compact</option><option value="comfortable">Comfortable</option><option value="roomy">Roomy</option></select></label><label className="db-setting-toggle"><input type="checkbox" checked={Boolean(config.wrap)} onChange={e=>void onConfig({wrap:e.target.checked})}/><span>Wrap cell content</span></label></>}{view.type==='gallery'&&<label className="db-setting-line"><span>Card size</span><select value={config.gallerySize||'medium'} onChange={e=>void onConfig({gallerySize:e.target.value as ViewConfig['gallerySize']})}><option value="small">Small</option><option value="medium">Medium</option><option value="large">Large</option></select></label>}<button className="db-delete-view" onClick={()=>void onDelete()}><Trash2/>Delete this view</button></>:section==='properties'?<PropertyVisibility fields={fields} config={config} onConfig={onConfig}/>:section==='filters'?<FilterEditor fields={fields} config={config} onConfig={onConfig}/>:<SortEditor fields={fields} config={config} onConfig={onConfig}/>}</div></aside>}
function SettingRow({label,value,onClick,icon,children}:{label:string;value:string;onClick:()=>void;icon?:React.ReactNode;children?:React.ReactNode}){return <div className="db-setting-row">{icon}<button onClick={onClick}><span>{label}</span><small>{value}</small>{children||<ChevronRight/>}</button></div>}
function PropertyVisibility({fields,config,onConfig}:{fields:Field[];config:ViewConfig;onConfig:(patch:Partial<ViewConfig>)=>Promise<void>}){const toggle=(id:string)=>{const hidden=config.hiddenFields.includes(id)?config.hiddenFields.filter(x=>x!==id):[...config.hiddenFields,id];void onConfig({hiddenFields:hidden})};return <div className="db-property-visibility"><div className="db-visibility-actions"><button onClick={()=>void onConfig({hiddenFields:[]})}>Show all</button><button onClick={()=>void onConfig({hiddenFields:fields.map(f=>f.id)})}>Hide all</button></div>{fields.map(f=><button key={f.id} onClick={()=>toggle(f.id)}><GripVertical/><PropertyIcon type={f.type}/><span>{f.name}</span>{config.hiddenFields.includes(f.id)?<EyeOff/>:<Eye/>}</button>)}</div>}
function FilterEditor({fields,config,onConfig}:{fields:Field[];config:ViewConfig;onConfig:(patch:Partial<ViewConfig>)=>Promise<void>}){const add=()=>void onConfig({filters:[...config.filters,{id:crypto.randomUUID(),fieldId:fields[0]?.id||'__title__',op:'equals',value:''}]});return <div className="db-rule-editor">{config.filters.map(rule=><div key={rule.id} className="db-rule"><select value={rule.fieldId} onChange={e=>void onConfig({filters:config.filters.map(r=>r.id===rule.id?{...r,fieldId:e.target.value}:r)})}><option value="__title__">Title</option>{fields.map(f=><option key={f.id} value={f.id}>{f.name}</option>)}</select><select value={rule.op} onChange={e=>void onConfig({filters:config.filters.map(r=>r.id===rule.id?{...r,op:e.target.value as FilterRule['op']}:r)})}><option value="equals">is</option><option value="not_equals">is not</option><option value="contains">contains</option><option value="empty">is empty</option><option value="not_empty">is not empty</option></select>{!['empty','not_empty'].includes(rule.op)&&<input value={rule.value} onChange={e=>void onConfig({filters:config.filters.map(r=>r.id===rule.id?{...r,value:e.target.value}:r)})}/>}<button onClick={()=>void onConfig({filters:config.filters.filter(r=>r.id!==rule.id)})}><X/></button></div>)}<button className="db-add-rule" onClick={add}><Plus/>Add filter</button></div>}
function SortEditor({fields,config,onConfig}:{fields:Field[];config:ViewConfig;onConfig:(patch:Partial<ViewConfig>)=>Promise<void>}){const add=()=>void onConfig({sorts:[...config.sorts,{id:crypto.randomUUID(),fieldId:'__title__',direction:'asc'}]});return <div className="db-rule-editor">{config.sorts.map(rule=><div key={rule.id} className="db-rule sort"><GripVertical/><select value={rule.fieldId} onChange={e=>void onConfig({sorts:config.sorts.map(r=>r.id===rule.id?{...r,fieldId:e.target.value}:r)})}><option value="__title__">Title</option>{fields.map(f=><option key={f.id} value={f.id}>{f.name}</option>)}</select><select value={rule.direction} onChange={e=>void onConfig({sorts:config.sorts.map(r=>r.id===rule.id?{...r,direction:e.target.value as 'asc'|'desc'}:r)})}><option value="asc">Ascending</option><option value="desc">Descending</option></select><button onClick={()=>void onConfig({sorts:config.sorts.filter(r=>r.id!==rule.id)})}><X/></button></div>)}<button className="db-add-rule" onClick={add}><Plus/>Add sort</button></div>}

function AutomationPanel({database,fields,automations,available,onClose,onChanged}:{database:Database;fields:Field[];automations:DatabaseAutomation[];available:boolean;onClose:()=>void;onChanged:()=>Promise<void>}){const[creating,setCreating]=useState(false);return <aside className="db-settings-panel"><header><div><span>AUTOMATIONS</span><strong>{database.name}</strong></div><button onClick={onClose}><X/></button></header><div className="db-settings-scroll">{!available?<div className="db-migration-note"><Bolt/><strong>Run migration 010_database_power.sql</strong><p>The automation table is not available in Supabase yet. The database itself will keep working normally.</p></div>:<>{automations.map(a=><div className="db-automation-card" key={a.id}><label><input type="checkbox" checked={a.enabled} onChange={async e=>{await updateAutomation(a.id,{enabled:e.target.checked});await onChanged()}}/><strong>{a.name}</strong></label><small>{automationSummary(a,fields)}</small><button onClick={async()=>{if(window.confirm(`Delete automation “${a.name}”?`)){await deleteAutomation(a.id);await onChanged()}}}><Trash2/></button></div>)}{creating?<AutomationCreator database={database} fields={fields} onCancel={()=>setCreating(false)} onAdded={async()=>{setCreating(false);await onChanged()}}/>:<button className="db-add-rule" onClick={()=>setCreating(true)}><Plus/>New automation</button>}</>}</div></aside>}
function AutomationCreator({database,fields,onCancel,onAdded}:{database:Database;fields:Field[];onCancel:()=>void;onAdded:()=>Promise<void>}){const[name,setName]=useState('New automation'),[trigger,setTrigger]=useState<AutomationTriggerType>('record_created'),[triggerField,setTriggerField]=useState(fields[0]?.id||''),[equals,setEquals]=useState(''),[action,setAction]=useState<AutomationActionType>('set_field'),[actionField,setActionField]=useState(fields[0]?.id||''),[value,setValue]=useState('');const add=async()=>{await createAutomation(database.id,{name:name.trim()||'Automation',enabled:true,trigger_type:trigger,trigger_config:trigger==='field_changed'?{field_id:triggerField,equals}:{},action_type:action,action_config:{field_id:actionField,value:action==='set_checkbox'?value==='true':value}});await onAdded()};return <div className="db-automation-creator"><input value={name} onChange={e=>setName(e.target.value)}/><span>When</span><select value={trigger} onChange={e=>setTrigger(e.target.value as AutomationTriggerType)}><option value="record_created">A record is created</option><option value="field_changed">A property changes</option></select>{trigger==='field_changed'&&<><select value={triggerField} onChange={e=>setTriggerField(e.target.value)}>{fields.map(f=><option key={f.id} value={f.id}>{f.name}</option>)}</select><input value={equals} onChange={e=>setEquals(e.target.value)} placeholder="Optional: only when value equals…"/></>}<span>Then</span><select value={action} onChange={e=>setAction(e.target.value as AutomationActionType)}><option value="set_field">Set a property</option><option value="set_today">Set a date to today</option><option value="set_checkbox">Set a checkbox</option></select><select value={actionField} onChange={e=>setActionField(e.target.value)}>{fields.map(f=><option key={f.id} value={f.id}>{f.name}</option>)}</select>{action==='set_field'&&<input value={value} onChange={e=>setValue(e.target.value)} placeholder="Value"/>}{action==='set_checkbox'&&<select value={value} onChange={e=>setValue(e.target.value)}><option value="true">Checked</option><option value="false">Unchecked</option></select>}<div className="db-popover-actions"><button onClick={onCancel}>Cancel</button><button className="primary" onClick={()=>void add()}>Create automation</button></div></div>}

function PropertyIcon({type}:{type:FieldType}){if(type==='number')return <span className="db-property-icon">#</span>;if(type==='date'||type==='created_time'||type==='last_edited_time')return <CalendarDays/>;if(type==='checkbox')return <span className="db-property-icon">☑</span>;if(type==='relation')return <span className="db-property-icon">↗</span>;if(type==='select'||type==='status')return <span className="db-property-icon">◉</span>;if(type==='multi_select')return <span className="db-property-icon">☷</span>;return <span className="db-property-icon">Aa</span>}
function optionStrings(field:Field){return Array.isArray(field.config?.options)?field.config.options.map(x=>typeof x==='string'?x:String((x as {name?:unknown})?.name||x)):[]}
function optionColorMap(field:Field):OptionColors{const raw=field.config?.optionColors;return raw&&typeof raw==='object'?raw as OptionColors:{}}
function splitOptions(value:string){return value.split(/\n|,/).map(x=>x.trim()).filter(Boolean)}
function cleanOptionColors(options:string[],colors:OptionColors){return Object.fromEntries(options.map((option,index)=>[option,colors[option]||DEFAULT_TAG_COLORS[index%DEFAULT_TAG_COLORS.length]]))}
function normalizeHex(value:string){return /^#[0-9a-f]{6}$/i.test(value)?value:'#e8e4dc'}
function tagStyle(color:string){const hex=normalizeHex(color);return {backgroundColor:hex,color:contrastColor(hex)} as React.CSSProperties}
function contrastColor(hex:string){const clean=hex.replace('#','');const r=parseInt(clean.slice(0,2),16),g=parseInt(clean.slice(2,4),16),b=parseInt(clean.slice(4,6),16);const luminance=(0.299*r+0.587*g+0.114*b)/255;return luminance>.68?'#3f3933':'#ffffff'}
function valueForField(record:RecordRow,field:Field){if(field.type==='created_time')return record.created_at;if(field.type==='last_edited_time')return record.updated_at;return record.data?.[field.id]}
function matchesFilter(record:RecordRow,rule:FilterRule,fields:Field[]){const field=fields.find(f=>f.id===rule.fieldId);const raw=rule.fieldId==='__title__'?record.title:field?valueForField(record,field):'';const value=formatValue(raw).toLowerCase(),needle=rule.value.toLowerCase();if(rule.op==='empty')return value==='';if(rule.op==='not_empty')return value!=='';if(rule.op==='equals')return value===needle;if(rule.op==='not_equals')return value!==needle;return value.includes(needle)}
function fieldTypeLabel(type:FieldType){return FIELD_TYPES.find(t=>t.value===type)?.label||type}
function formatValue(value:unknown){if(Array.isArray(value))return value.join(', ');if(value===true)return'Yes';if(value===false)return'No';return String(value??'')}
function formatDate(value:string){try{return new Intl.DateTimeFormat(undefined,{dateStyle:'medium',timeStyle:'short'}).format(new Date(value))}catch{return value}}
function compare(a:unknown,b:unknown){const an=typeof a==='number'?a:Number.NaN,bn=typeof b==='number'?b:Number.NaN;if(!Number.isNaN(an)&&!Number.isNaN(bn))return an-bn;return formatValue(a).localeCompare(formatValue(b),undefined,{numeric:true,sensitivity:'base'})}
function capitalize(value:string){return value.charAt(0).toUpperCase()+value.slice(1)}
function automationSummary(a:DatabaseAutomation,fields:Field[]){const name=(id:unknown)=>fields.find(f=>f.id===String(id))?.name||'property';const trigger=a.trigger_type==='record_created'?'When a record is created':`When ${name(a.trigger_config?.field_id)} changes${a.trigger_config?.equals?` to ${a.trigger_config.equals}`:''}`;const action=a.action_type==='set_today'?`set ${name(a.action_config?.field_id)} to today`:a.action_type==='set_checkbox'?`set ${name(a.action_config?.field_id)} ${a.action_config?.value?'checked':'unchecked'}`:`set ${name(a.action_config?.field_id)} to ${String(a.action_config?.value??'')}`;return `${trigger}, ${action}.`}
